#include <pybind11/complex.h>
#include <pybind11/pybind11.h>
#include <pybind11/stl.h>

namespace py = pybind11;

#include <gnuradio/rad_astro/avg.h>
// pydoc.h is automatically generated in the build directory
#include <avg_pydoc.h>

void bind_avg(py::module& m)
{

    using avg    = ::gr::rad_astro::avg;


    py::class_<avg, gr::block, gr::basic_block,
        std::shared_ptr<avg>>(m, "avg", D(avg))

        .def(py::init(&avg::make),
           py::arg("vlen"),
           py::arg("numAvgs"),
           py::arg("avgType"),
           py::arg("alpha"),
           py::arg("beta"),
           py::arg("delta"),
           py::arg("gamma"),
           D(avg,make)
        )
        



        ;




}








